import{_ as s,o as t,c as a,ag as r}from"./chunks/framework.DB9Ll7VW.js";const h=JSON.parse('{"title":"Courses & curriculum","description":"A field-by-field walkthrough of the Sikshya Course Builder — every tab, every option — so you can build a great course on the first try.","frontmatter":{"title":"Courses & curriculum","description":"A field-by-field walkthrough of the Sikshya Course Builder — every tab, every option — so you can build a great course on the first try."},"headers":[],"relativePath":"courses.md","filePath":"courses.md","lastUpdated":1778327862000}'),o={name:"courses.md"};function i(n,e,l,c,u,d){return t(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="courses-curriculum" tabindex="-1">Courses &amp; curriculum <a class="header-anchor" href="#courses-curriculum" aria-label="Permalink to &quot;Courses &amp; curriculum&quot;">​</a></h1><p>This page walks you through every screen and field for building a Sikshya course. If you just want to ship something fast, follow the <a href="/docs/quick-start">Quick start</a> first, then come back here when you need to fine-tune.</p><h2 id="the-courses-list" tabindex="-1">The Courses list <a class="header-anchor" href="#the-courses-list" aria-label="Permalink to &quot;The Courses list&quot;">​</a></h2><p>Open <span class="screen-path">Sikshya → Course → Courses</span>.</p><p>You&#39;ll see a table of every course on your site with:</p><ul><li>A <strong>Search</strong> box (search by title).</li><li><strong>Status pills</strong> at the top: All, Published, Draft, Pending, Scheduled, Private, Trash.</li><li><strong>Course type</strong> dropdown: All types, Regular, Subscription <span class="pro-pill">PRO</span>, Bundle <span class="pro-pill">PRO</span>.</li><li><strong>Sort by</strong>: Title, Published, Last modified, ID, Author.</li><li>A <strong>+ Add new course</strong> button in the top right.</li></ul><p>Each row shows: ID, image, title (with a Bundle / Subscription chip if applicable), categories, price, level, published / updated dates, and status.</p><p>Click any row to <strong>Edit in builder</strong>. Tick rows for <strong>Bulk actions</strong>: Move to trash, Publish, Move to draft, Mark pending review, Move to private. (In the Trash tab the bulk options become <strong>Restore to draft</strong> or <strong>Delete permanently</strong>.)</p><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Manage course staff (multi-instructor)</span></div><p class="pro-callout__desc">When the <strong>Multi-instructor</strong> add-on is on, each row gets a <strong>Manage staff</strong> action so you can add co-instructors, set roles (Owner / Editor / Grader), and split revenue.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock multi-instructor →</a></div><h2 id="the-course-builder-—-4-tabs" tabindex="-1">The Course Builder — 4 tabs <a class="header-anchor" href="#the-course-builder-—-4-tabs" aria-label="Permalink to &quot;The Course Builder — 4 tabs&quot;">​</a></h2><p>Click <strong>+ Add new course</strong> (or click any course title) to open the <strong>Course Builder</strong>. It has four tabs at the top:</p><ol><li><strong>Course details</strong> — what the course is.</li><li><strong>Pricing &amp; access</strong> — how learners get in.</li><li><strong>Curriculum</strong> — the actual lessons, quizzes, and assignments.</li><li><strong>Course options</strong> — visibility, completion rules, certificates, reviews.</li></ol><p>Top-right buttons stay sticky while you work: <strong>Preview</strong>, <strong>Save draft</strong>, <strong>Publish</strong>.</p><h2 id="tab-1-—-course-details" tabindex="-1">Tab 1 — Course details <a class="header-anchor" href="#tab-1-—-course-details" aria-label="Permalink to &quot;Tab 1 — Course details&quot;">​</a></h2><p>This is everything visible on the public course page. Sections in order:</p><h3 id="basic-information" tabindex="-1">Basic information <a class="header-anchor" href="#basic-information" aria-label="Permalink to &quot;Basic information&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Course title</strong></td><td>The headline learners see.</td></tr><tr><td><strong>URL slug</strong> (permalink)</td><td>Auto-generated from the title; click to edit.</td></tr><tr><td><strong>Short teaser</strong></td><td>One-line subtitle on the catalog card.</td></tr><tr><td><strong>Full description</strong></td><td>The long pitch, rendered in the WordPress editor.</td></tr><tr><td><strong>Primary category</strong></td><td>Pick from your course categories (manage them under <span class="screen-path">Course → Categories</span>).</td></tr><tr><td><strong>Difficulty level</strong></td><td>Beginner / Intermediate / Advanced. Used in catalog filters.</td></tr><tr><td><strong>Estimated length</strong></td><td>In hours. Shows on the catalog card.</td></tr><tr><td><strong>Instruction language</strong></td><td>English, Spanish, etc. Useful for multilingual catalogs.</td></tr><tr><td><strong>Target audience</strong></td><td>Who this course is for, in plain language.</td></tr></tbody></table><h3 id="images-video" tabindex="-1">Images &amp; video <a class="header-anchor" href="#images-video" aria-label="Permalink to &quot;Images &amp; video&quot;">​</a></h3><ul><li><strong>Featured image</strong> — the big image at the top of the course page and in catalog cards.</li><li><strong>Course trailer video (URL)</strong> — paste a YouTube or Vimeo link. Plays inline on the course page.</li></ul><h3 id="what-students-will-learn" tabindex="-1">What students will learn <a class="header-anchor" href="#what-students-will-learn" aria-label="Permalink to &quot;What students will learn&quot;">​</a></h3><ul><li><strong>Learning outcomes</strong> — a bulleted list. Click <strong>+ Add outcome</strong> to append more.</li><li><strong>Course highlights</strong> — 4–6 short brag points (e.g. &quot;30+ lessons&quot;, &quot;Lifetime access&quot;).</li><li><strong>FAQ</strong> — Question + Answer pairs. Click <strong>+ Add FAQ item</strong> for more.</li><li><strong>Downloadable resources</strong> — files learners can download. Each has a Title, a media file, or a direct URL.</li><li><strong>Announcements</strong> — pinned notes for enrolled learners (Title, Message, Date).</li></ul><h3 id="instructor" tabindex="-1">Instructor <a class="header-anchor" href="#instructor" aria-label="Permalink to &quot;Instructor&quot;">​</a></h3><ul><li><strong>Who teaches this course?</strong> — pick a user with the <strong>Sikshya Instructor</strong> role.</li></ul><h3 id="search-engine-listing-seo" tabindex="-1">Search engine listing (SEO) <a class="header-anchor" href="#search-engine-listing-seo" aria-label="Permalink to &quot;Search engine listing (SEO)&quot;">​</a></h3><ul><li><strong>SEO title</strong> — overrides the page title for search engines.</li><li><strong>Meta description</strong> — the snippet under your link in search results.</li><li><strong>Focus keywords</strong> — for tracking with Yoast / Rank Math / SEOPress.</li></ul><h2 id="tab-2-—-pricing-access" tabindex="-1">Tab 2 — Pricing &amp; access <a class="header-anchor" href="#tab-2-—-pricing-access" aria-label="Permalink to &quot;Tab 2 — Pricing &amp; access&quot;">​</a></h2><p>How learners pay and who can join.</p><h3 id="how-people-pay" tabindex="-1">How people pay <a class="header-anchor" href="#how-people-pay" aria-label="Permalink to &quot;How people pay&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Free Course</strong></td><td>Learners enroll with one click. No checkout step.</td></tr><tr><td><strong>Paid Course</strong></td><td>Standard one-time purchase via your active gateway.</td></tr><tr><td><strong>Subscription only</strong> <span class="pro-pill">PRO</span></td><td>Course is part of a subscription plan (membership).</td></tr></tbody></table><h3 id="pricing-fields" tabindex="-1">Pricing fields <a class="header-anchor" href="#pricing-fields" aria-label="Permalink to &quot;Pricing fields&quot;">​</a></h3><ul><li><strong>Regular price</strong> — the normal price.</li><li><strong>Sale price</strong> — optional. When set, this is the price learners pay.</li><li><strong>Membership plan</strong> <span class="pro-pill">PRO</span> — if you picked Subscription Only, choose the plan.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Course bundles &amp; subscriptions</span></div><p class="pro-callout__desc">Sell several courses for one bundled price (Course Bundles add-on), or charge monthly / yearly recurring fees for member-only access (Subscriptions add-on).</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock pricing options →</a></div><h3 id="who-can-sign-up" tabindex="-1">Who can sign up? <a class="header-anchor" href="#who-can-sign-up" aria-label="Permalink to &quot;Who can sign up?&quot;">​</a></h3><ul><li><strong>Open</strong> — anyone can buy / enroll.</li><li><strong>Closed</strong> — disabled for now.</li><li><strong>Invite only</strong> — admin enrollment only.</li></ul><h3 id="other-access-fields" tabindex="-1">Other access fields <a class="header-anchor" href="#other-access-fields" aria-label="Permalink to &quot;Other access fields&quot;">​</a></h3><ul><li><strong>Maximum students</strong> — optional cap.</li><li><strong>Course start / end</strong> — optional schedule.</li><li><strong>Enrollment opens / closes</strong> — optional date range.</li></ul><h3 id="prerequisites-requirements" tabindex="-1">Prerequisites &amp; requirements <a class="header-anchor" href="#prerequisites-requirements" aria-label="Permalink to &quot;Prerequisites &amp; requirements&quot;">​</a></h3><ul><li><strong>Prerequisites</strong> <span class="pro-pill">PRO</span> — courses or lessons that must be completed before enrolling.</li><li><strong>Course requirements</strong> — text-only &quot;you need a Mac and Photoshop&quot; style notes (free).</li></ul><h2 id="tab-3-—-curriculum" tabindex="-1">Tab 3 — Curriculum <a class="header-anchor" href="#tab-3-—-curriculum" aria-label="Permalink to &quot;Tab 3 — Curriculum&quot;">​</a></h2><p>This is where you build the actual learning experience. Curriculum is organized as:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Course</span></span>
<span class="line"><span>└── Chapter</span></span>
<span class="line"><span>    ├── Lesson</span></span>
<span class="line"><span>    ├── Quiz</span></span>
<span class="line"><span>    └── Assignment</span></span></code></pre></div><p>You&#39;ll see an <strong>outline</strong> down the left and a <strong>builder</strong> on the right.</p><ol class="step-list"><li>Click <strong>+ Add chapter</strong> at the top. Type a chapter name like &quot;Module 1 — Foundations&quot; and click Save.</li><li>Inside the chapter, click <strong>+ Add lesson</strong>. A modal opens with lesson types: <strong>Text</strong>, <strong>Video</strong>, plus Live class <span class="pro-pill">PRO</span>, SCORM <span class="pro-pill">PRO</span>, H5P <span class="pro-pill">PRO</span>.</li><li>Pick <strong>Text</strong>, type a lesson title, click <strong>Create</strong>. The lesson opens in the editor — write the body, attach downloadable files, save.</li><li>Back in the curriculum, drag chapters and lessons to reorder. Click any lesson to re-edit it.</li><li>Repeat: <strong>+ Add quiz</strong>, <strong>+ Add assignment</strong>. Quizzes have their own editor — see below.</li></ol><h3 id="lesson-types" tabindex="-1">Lesson types <a class="header-anchor" href="#lesson-types" aria-label="Permalink to &quot;Lesson types&quot;">​</a></h3><ul><li><strong>Text</strong> — paragraphs, headings, images, embedded media. The standard WordPress editor.</li><li><strong>Video</strong> — paste a YouTube, Vimeo, or any embeddable video URL.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Live classes, SCORM, and H5P</span></div><p class="pro-callout__desc">Pin a Zoom or Google Meet URL to a lesson so learners always click the right link (Live classes add-on). Or embed a packaged SCORM / H5P interactive (SCORM/H5P add-on).</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock these lesson types →</a></div><h3 id="quizzes" tabindex="-1">Quizzes <a class="header-anchor" href="#quizzes" aria-label="Permalink to &quot;Quizzes&quot;">​</a></h3><p>Click any quiz to open the quiz editor. It has three sub-tabs:</p><ul><li><strong>Content</strong> — title, description, intro text.</li><li><strong>Settings</strong> — passing score (%), attempts allowed, time limit (minutes).</li><li><strong>Questions</strong> — pick from your <strong>Question library</strong> or click <strong>+ New question</strong> to write one.</li></ul><p>Free question types:</p><ul><li>Multiple choice (single or multi-correct answers).</li><li>True / false.</li><li>Short answer (one line of text).</li><li>Fill in the blank.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Advanced quiz types &amp; question banks</span></div><p class="pro-callout__desc">Reuse questions across many quizzes from a central <strong>Question bank</strong>. Add advanced question types, randomize order, draw a random pool of questions per learner, or shuffle answers each attempt — all in the <strong>Advanced quiz types</strong> add-on.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock advanced quizzes →</a></div><h3 id="assignments" tabindex="-1">Assignments <a class="header-anchor" href="#assignments" aria-label="Permalink to &quot;Assignments&quot;">​</a></h3><p>Each assignment has a title, description, due date, and a file-upload field for learner submissions. After submission, you grade pass / fail with a free-text note.</p><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Advanced assignments &amp; gradebook</span></div><p class="pro-callout__desc">Score against a rubric, restrict the file types learners can upload, allow resubmissions, and see a per-learner / per-course grade view with the <strong>Advanced assignments</strong> + <strong>Gradebook</strong> add-ons.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock grading workflows →</a></div><h2 id="tab-4-—-course-options" tabindex="-1">Tab 4 — Course options <a class="header-anchor" href="#tab-4-—-course-options" aria-label="Permalink to &quot;Tab 4 — Course options&quot;">​</a></h2><p>Final settings: visibility, completion rules, reviews, certificates.</p><h3 id="visibility-catalog" tabindex="-1">Visibility &amp; catalog <a class="header-anchor" href="#visibility-catalog" aria-label="Permalink to &quot;Visibility &amp; catalog&quot;">​</a></h3><ul><li><strong>Who can see this course?</strong> — Draft, Published, Private, Password protected.</li><li><strong>Course password</strong> — if Password protected.</li><li><strong>Featured course</strong> — show with a badge in the catalog.</li><li><strong>Featured badge text</strong> — the badge label (e.g. &quot;Editor&#39;s pick&quot;).</li><li><strong>Hide from catalog</strong> — useful for invite-only or bundled-only courses.</li><li><strong>Require prerequisites before enrollment</strong> <span class="pro-pill">PRO</span>.</li><li><strong>Disable email marketing sync for this course</strong> <span class="pro-pill">PRO</span> — when integrated with Mailchimp / MailerLite, exclude this course from list syncs.</li></ul><h3 id="completion-progress" tabindex="-1">Completion &amp; progress <a class="header-anchor" href="#completion-progress" aria-label="Permalink to &quot;Completion &amp; progress&quot;">​</a></h3><ul><li><strong>When is the course finished?</strong> — All lessons complete / All lessons + quizzes + assignments / Pass all quizzes / Manual.</li><li><strong>Minimum quiz score (%)</strong> — only relevant for the &quot;Pass all quizzes&quot; rule.</li><li><strong>Require a final quiz</strong> — last quiz must be passed for completion.</li><li><strong>Track student progress</strong> — leave on. Powers the progress bar and certificate.</li></ul><h3 id="reviews-pro" tabindex="-1">Reviews <span class="pro-pill">PRO</span> <a class="header-anchor" href="#reviews-pro" aria-label="Permalink to &quot;Reviews &lt;span class=&quot;pro-pill&quot;&gt;PRO&lt;/span&gt;&quot;">​</a></h3><ul><li><strong>Allow course reviews</strong> — when <strong>Course reviews &amp; ratings</strong> add-on is on, this section shows up. Toggle reviews on / off per course.</li></ul><h3 id="certificates" tabindex="-1">Certificates <a class="header-anchor" href="#certificates" aria-label="Permalink to &quot;Certificates&quot;">​</a></h3><ul><li><strong>Enable completion certificate</strong> — toggle on to issue a certificate when the course is complete.</li><li><strong>Certificate requires course completion</strong> — vs. &quot;issue at progress threshold.&quot;</li><li><strong>Certificate template</strong> — pick from your installed templates (free presets: <strong>Regalia</strong>, <strong>Vertex</strong>).</li><li><strong>Progress threshold for certificate (%)</strong> — issue early at e.g. 80% if you&#39;d rather not require 100%.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Advanced certificates with verification</span></div><p class="pro-callout__desc">Build certificates with a drag-and-drop designer, more merge fields (instructor, score, serial), and add a <strong>QR code</strong> that links to a public verify page so anyone can confirm authenticity.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock advanced certificates →</a></div><h2 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h2><p>Open <span class="screen-path">Sikshya → Course → Categories</span> to manage course categories. Each category has:</p><ul><li><strong>Name</strong> — visible in catalogs and on the card.</li><li><strong>Description</strong> — long form, rich text. Shows on the category archive.</li><li><strong>Slug</strong> — auto-generated; edit if you want a specific URL.</li><li><strong>Parent</strong> — categories are hierarchical. &quot;Web development → Frontend → CSS&quot; is fine.</li><li><strong>Image</strong> — optional category image used on archive headers.</li></ul><p>You can search, sort, and bulk-delete categories from this screen.</p><h2 id="other-content-libraries" tabindex="-1">Other content libraries <a class="header-anchor" href="#other-content-libraries" aria-label="Permalink to &quot;Other content libraries&quot;">​</a></h2><p>Open <span class="screen-path">Sikshya → Course → Content library</span> for direct access to your stand-alone content:</p><ul><li><strong>Lessons</strong> — all lessons across all courses.</li><li><strong>Quizzes</strong> — all quizzes.</li><li><strong>Assignments</strong> — all assignments.</li><li><strong>Questions</strong> — your question library (reusable across quizzes).</li><li><strong>Chapters</strong> — chapters across courses.</li><li><strong>Question banks</strong> <span class="pro-pill">PRO</span> — only visible when <strong>Advanced quiz types</strong> is on.</li></ul><p>These tabs use the same WordPress list pattern (search, status pills, sort, bulk actions). Use them when you want to clean up unused lessons or move a question between quizzes.</p><h2 id="tips-best-practices" tabindex="-1">Tips &amp; best practices <a class="header-anchor" href="#tips-best-practices" aria-label="Permalink to &quot;Tips &amp; best practices&quot;">​</a></h2><ul><li><strong>Keep chapter titles short</strong> (under 60 characters). They show in the curriculum sidebar.</li><li><strong>Use preview lessons.</strong> Tag the first lesson of each chapter as a preview lesson so anonymous visitors can sample before they buy.</li><li><strong>Aim for short lessons</strong> (5–10 minutes). Completion rates go up dramatically.</li><li><strong>Use categories for level</strong>, <strong>tags for topics</strong>. Both feed your catalog filters.</li><li><strong>One course, one outcome.</strong> &quot;Master Excel pivot tables&quot; beats &quot;Become a spreadsheet wizard&quot; because it&#39;s specific.</li></ul><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="/docs/learners">Learners &amp; roles</a> — manage students, instructors, and enrollments.</li><li><a href="/docs/enrollment-settings">Enrollment &amp; access</a> — drip, prerequisites, manual enroll.</li><li><a href="/docs/payment-settings">Payments</a> — gateways and refunds.</li><li><a href="/docs/third-party-integrations">Pro add-ons</a> — every Pro feature listed.</li></ul>`,78)])])}const g=s(o,[["render",i]]);export{h as __pageData,g as default};
